<?php header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/conexion.php';$keys=['yape_numero','plin_numero','titular_pago','banco_transferencia','cuenta_transferencia','cci_transferencia'];$out=[];try{$q=$pdo->prepare('SELECT clave,valor FROM configuracion WHERE clave IN ('.implode(',',array_fill(0,count($keys),'?')).')');$q->execute($keys);foreach($q->fetchAll() as $r)$out[$r['clave']]=$r['valor'];}catch(Throwable $e){}echo json_encode(['success'=>true,'data'=>$out],JSON_UNESCAPED_UNICODE);
